                               ((HEAD_DIM_VO / 16) % NUM_WARPS_KV == 0) &&
                               (HEAD_DIM_QK == HEAD_DIM_VO) &&
                               (sizeof(DTypeKV) == 2 || CTA_TILE_Q > 16);
    constexpr bool kSinglePrefillVOSplitDispatch =
        AttentionVariant::use_softmax && is_fp4_type_v<DTypeKV> && (HEAD_DIM_VO / 16 > 16) &&
        ((HEAD_DIM_VO / 16) % NUM_WARPS_KV == 0);
