      std::ostringstream err_msg;
      err_msg << "Even the smallest KV tile for head_dim_qk=" << HEAD_DIM_QK
              << ", head_dim_vo=" << HEAD_DIM_VO << ", cta_tile_q=" << CTA_TILE_Q
              << " exceeds this GPU's " << max_smem_per_block_optin
