              auto lse = params.lse;
              params.o = tmp;
              params.lse = tmp_lse;
              void* args[] = {(void*)&params};
              dim3 nblks(ceil_div(qo_len * group_size, CTA_TILE_Q), num_chunks, num_kv_heads);
              dim3 nthrs(32, NUM_WARPS_Q, NUM_WARPS_KV);

