__device__ __forceinline__ b128_t hyle_prefetch_packed_k_vector(const void* source, bool valid) {
  b128_t packed{};
  if (valid) {
    // Read raw packed K before softmax. Decode and publication remain below.
    asm volatile("ld.global.v4.u32 {%0,%1,%2,%3}, [%4];"
                 : "=r"(packed.x), "=r"(packed.y), "=r"(packed.z), "=r"(packed.w)
                 : "l"(source) : "memory");
  }
  return packed;
}

template <typename KTraits>
__device__ __forceinline__ void hyle_store_prefetched_k_vector(
    smem_t<KTraits::SWIZZLE_MODE_KV> smem, b128_t packed, uint32_t row, uint32_t col) {
  static_assert(hyle_bf16_k_pair_prefetch_scope<KTraits>);
  alignas(16) typename KTraits::DTypeQ converted[16];
  vec_cast<typename KTraits::DTypeQ, typename KTraits::DTypeKV>::template cast<16>(
      converted, reinterpret_cast<typename KTraits::DTypeKV*>(&packed));
  constexpr uint32_t stride = 256 / upcast_size<typename KTraits::DTypeQ>();
  smem.base[get_permuted_offset<KTraits::SWIZZLE_MODE_KV, stride>(row, 2 * col)] =
      *reinterpret_cast<b128_t*>(converted);
  smem.base[get_permuted_offset<KTraits::SWIZZLE_MODE_KV, stride>(row, 2 * col + 1)] =
      *reinterpret_cast<b128_t*>(converted + 8);
}

template <typename KTraits, typename SmemStorage>
__device__ __forceinline__ void hyle_publish_prefetched_k_pair(
    SmemStorage* storage, uint32_t next_base, uint32_t chunk_size,
    uint32_t warp_idx, uint32_t lane_idx, b128_t first, b128_t second) {
  static_assert(hyle_bf16_k_pair_prefetch_scope<KTraits>);
  const uint32_t row = warp_idx * 4 + lane_idx / 8;
  if (next_base + row >= chunk_size) return;  // Original K kNoFill behavior.
  smem_t<KTraits::SWIZZLE_MODE_KV> smem(storage->k_smem);
  const uint32_t col = lane_idx % 8;
  hyle_store_prefetched_k_vector<KTraits>(smem, first, row, col);
  hyle_store_prefetched_k_vector<KTraits>(smem, second, row, col + 8);
}

